653	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
654	func formatFloat(v float64) string {
655		return strconv.FormatFloat(v, 'g', -1, 64)
656	}
657	
658	type parsedQuery struct {
659		name   string
660		start  int64
661		end    int64
662		labels map[string]string
663	}
664	
665	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
666	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
667		q, err := parseQuery(raw)
668		if err != nil {
669			return nil, &LineError{Status: "error", Error: err.Error()}
670		}
671		if q.start > q.end {
672			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
673				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
674		}
675		return s.runQuery(q), nil
676	}
677	
678	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
679	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
680	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
681		var q parsedQuery
682		err := parseStrictObject(raw,
683			"each query must be a JSON object",
684			"unexpected content after the query object",
685			[]string{"op", "name", "start", "end"},
686			map[string]fieldReader{
687				"op": func(dec *json.Decoder) error {
688					t, err := dec.Token()
689					if err != nil {
690						return err
691					}
692					op, ok := t.(string)
693					if !ok {
694						return fmt.Errorf(`field "op" must be a string`)
695					}
696					if op != "query" {
697						return fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
698					}
699					return nil
700				},
701				"name":  func(dec *json.Decoder) error { return readNameField(dec, &q.name) },
702				"start": func(dec *json.Decoder) error { return readInt64Field(dec, "start", &q.start) },
703				"end":   func(dec *json.Decoder) error { return readInt64Field(dec, "end", &q.end) },
704				"labels": func(dec *json.Decoder) error {
705					return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
706				},
707			})
708		return q, err
709	}
710	
711	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
712	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
713	func labelsMatch(want, stored map[string]string) bool {
714		for k, v := range want {
715			got, ok := stored[k]
716			if !ok || got != v {
717				return false
718			}
719		}
720		return true
721	}
722	
723	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
724	// 序列次序与写入快照共用 organizeSeries 的整理结果：过滤掉其他序列后，
725	// 保留的序列仍是同一排序中的一个子序列，不另换排序；无区间内点的序列不列出。
726	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
727		inRange := func(ts int64) bool { return ts >= q.start && ts <= q.end }
728		out := make([]QuerySeries, 0)
729		for _, os := range s.organizeSeries() {
730			if os.ref.Name != q.name || !labelsMatch(q.labels, os.ref.Labels) {
731				continue
732			}
733			points := sortedSeriesPoints(os.sr, inRange)
734			if len(points) == 0 {
735				continue
736			}
737			values := make([]float64, len(points))
738			for i, p := range points {
739				values[i] = p.Value
740			}
741			out = append(out, QuerySeries{
742				Name:    os.ref.Name,
743				Labels:  os.ref.Labels,
744				Count:   len(values),
745				Average: finiteMean(values),
746			})
747		}
748		return &QueryResult{Status: "ok", Op: "query", Series: out}
749	}
750	
751	// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
752	// 恰好在两个相邻可表示值中间时按最近偶数舍入。
753	// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
754	// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
755	// 只有一个点时结果就是该点的值。
756	func finiteMean(values []float64) float64 {
757		sum := new(big.Rat)
758		r := new(big.Rat)
759		for _, v := range values {
760			// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
761			sum.Add(sum, r.SetFloat64(v))
762		}
763		sum.Quo(sum, r.SetInt64(int64(len(values))))
764		return ratToFloat64NearestEven(sum)
765	}
766	
767	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
768	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
769	func ratToFloat64NearestEven(x *big.Rat) float64 {
770		if x.Sign() == 0 {
771			return 0
772		}
773		num := new(big.Int).Set(x.Num())
774		den := x.Denom()
775		neg := num.Sign() < 0
776		if neg {
777			num.Neg(num)
778		}
779	
780		// e 满足 2^e <= num/den < 2^(e+1)。
781		e := floorLog2Rat(num, den)
782		var m *big.Int
783		scale := 0
784		if e >= -1022 {
785			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
786			scale = e - 52
787			m = roundScaledRatio(num, den, scale)
788			if m.BitLen() == 54 {
789				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
790				m.Rsh(m, 1)
791				scale++
792			}
793		} else {
794			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
795			scale = -1074
796			m = roundScaledRatio(num, den, scale)
797		}
798		// m < 2^53，可以精确放入 int64 与 float64。
799		f := math.Ldexp(float64(m.Int64()), scale)
800		if neg {
801			return -f
802		}
803		return f
804	}
805	
806	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
807	func floorLog2Rat(num, den *big.Int) int {
808		k := num.BitLen() - den.BitLen()
809		var t big.Int
810		if k >= 0 {
811			t.Lsh(den, uint(k))
812			if num.Cmp(&t) >= 0 {
813				return k
814			}
815			return k - 1
816		}
817		t.Lsh(num, uint(-k))
818		if t.Cmp(den) >= 0 {
819			return k
820		}
821		return k - 1
822	}
823	
824	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
825	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
826		n := new(big.Int).Set(num)
827		d := new(big.Int).Set(den)
828		if scale >= 0 {
829			d.Lsh(d, uint(scale))
830		} else {
831			n.Lsh(n, uint(-scale))
832		}
833		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
834		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
835		case 1:
836			q.Add(q, big.NewInt(1))
837		case 0:
838			if q.Bit(0) == 1 {
839				q.Add(q, big.NewInt(1))
840			}
841		}
842		return q
843	}
844	
845	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
846	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
847	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
848	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
849	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
850	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
851	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
852	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
853	func (r SeriesRef) String() string {
854		var b strings.Builder
855		b.WriteString(identityText(r.Name))
856		b.WriteByte('{')
857		for i, p := range sortedPairs(r.Labels) {
858			if i > 0 {
859				b.WriteByte(',')
860			}
861			b.WriteString(identityText(p.Key))
862			b.WriteByte('=')
863			b.WriteString(identityText(p.Value))
864		}
865		b.WriteByte('}')
866		return b.String()
867	}
868	
869	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
870	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
871	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
872	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
873	// 因此渲染结果不会把内容字符误读为标签边界。
874	func identityText(s string) string {
875		if s == "" || s != strings.TrimSpace(s) {
876			return strconv.Quote(s)
877		}
878		for _, r := range s {
879			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
880				return strconv.Quote(s)
881			}
882		}
883		return s
884	}
885	
886	// organizedSeries 是一次结果整理中的一条序列：携带已存序列指针、
887	// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
888	// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
889	// 整理好的键值对，供排序比较直接复用。
890	type organizedSeries struct {
891		sr    *storedSeries
892		ref   SeriesRef
893		pairs []labelPair
894	}
895	
896	// organizeSeries 是写入快照与区间查询共用的数据整理逻辑：
897	// 遍历全部已提交序列，复制各自的序列身份，并按唯一的顺序约定排列——
898	// 先按指标名字符串字典序，再按标签键升序后的键值对逐对比较
899	// （先比键再比值，前一对相同才比下一对；较短集合是完整前缀时排前，
900	// 无标签序列因此排在最前）。标签值按字符串比较（"10" 在 "2" 之前）。
901	// 每条序列的标签只在遍历时整理一次：排序后的键值对随条目保留，
902	// sort 的反复比较直接复用同一份结果，不会因一条序列参与多次比较
903	// 而反复整理同一套标签。整理结果不复制采样点；采样点的选取与升序
904	// 排列由 sortedSeriesPoints 完成。
905	func (s *MetricStore) organizeSeries() []organizedSeries {
906		out := make([]organizedSeries, 0, len(s.series))
907		for _, sr := range s.series {
908			// 标签必须复制：成功结果是当次操作的独立记录，
909			// 调用方修改结果标签不能改动已存序列的身份。
910			labels := cloneLabels(sr.ref.Labels)
911			out = append(out, organizedSeries{
912				sr:    sr,
913				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
914				pairs: sortedPairs(labels),
915			})
916		}
917		sort.Slice(out, func(i, j int) bool {
918			if out[i].ref.Name != out[j].ref.Name {
919				return out[i].ref.Name < out[j].ref.Name
920			}
921			return compareLabelPairs(out[i].pairs, out[j].pairs) < 0
922		})
923		return out
924	}
925	
926	// sortedSeriesPoints 按 timestamp 升序返回一条已存序列中满足 keep 的采样点，
927	// 数值与时间戳一一对应。keep 为 nil 时返回全部点（写入快照）；
928	// 区间查询传入闭区间判定，查询只选取区间内的点。
929	// 返回的是新建切片与新建 Point，调用方对采样点的修改不影响存储，
930	// 也不影响此前或此后取得的其他成功结果。
931	func sortedSeriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
932		tsList := make([]int64, 0, len(sr.points))
933		for ts := range sr.points {
934			if keep == nil || keep(ts) {
935				tsList = append(tsList, ts)
936			}
937		}
938		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
939		points := make([]Point, len(tsList))
940		for i, ts := range tsList {
941			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
942		}
943		return points
944	}
945	
946	// snapshot 生成按规范排序的全部序列视图：序列次序与点排列均来自
947	// organizeSeries/sortedSeriesPoints 这套与查询共用的整理逻辑。
948	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
949		organized := s.organizeSeries()
950		views := make([]SeriesView, 0, len(organized))
951		for _, os := range organized {
952			views = append(views, SeriesView{
953				Name:   os.ref.Name,
954				Labels: os.ref.Labels,
955				Points: sortedSeriesPoints(os.sr, nil),
956			})
957		}
958		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
959	}
960

