	secondValues := []string{
		`1`,       // 数字
		`true`,    // 布尔
		`null`,    // null
		`{"x":1}`, // 对象
		`[1,2]`,   // 数组
		`"a"`,     // 与第一个值相同的字符串
		`"b"`,     // 不同字符串
		`""`,      // 空字符串（空值合法，但键仍重复）
		`3.5`,     // 小数
		`-2`,      // 负整数
